index c266f4ec102c76b48dbfe7fa6d95b32f98babb11..4e418ad2841f16f5100cb9df0645f2d96ad93bfc
--- a/balancer/balancer.go
+++ b/balancer/balancer.go
@@ -35,6 +35,10 @@
 	"google.golang.org/grpc/serviceconfig"
 )

+// ErrBadResolverState indicates that a balancer cannot use the resolver state
+// it received and requests that the resolver try again.
+var ErrBadResolverState = errors.New("bad resolver state")
+
 var (
 	// m is a map from name to balancer builder.
 	m = make(map[string]Builder)
@@ -312,7 +316,9 @@
 type V2Balancer interface {
 	// UpdateClientConnState is called by gRPC when the state of the ClientConn
 	// changes.
-	UpdateClientConnState(ClientConnState)
+	UpdateClientConnState(ClientConnState) error
+	// ResolverError is called when the resolver reports an error.
+	ResolverError(error)
 	// UpdateSubConnState is called by gRPC when the state of a SubConn
 	// changes.
 	UpdateSubConnState(SubConn, SubConnState)
diff --git a/balancer_conn_wrappers.go b/balancer_conn_wrappers.go
index 8df4095ca95177f131076b8fe5717b4cf70a9b0d..3c98ee6bba875108dcdcf5055515d22e3556b4df
--- a/balancer_conn_wrappers.go
+++ b/balancer_conn_wrappers.go
@@ -19,6 +19,7 @@
 package grpc

 import (
+	"errors"
 	"fmt"
 	"sync"

@@ -89,6 +90,7 @@
 	balancer         balancer.Balancer
 	stateChangeQueue *scStateUpdateBuffer
 	ccUpdateCh       chan *balancer.ClientConnState
+	resolverErrCh    chan error
 	done             chan struct{}

 	mu       sync.Mutex
@@ -100,6 +102,7 @@
 		cc:               cc,
 		stateChangeQueue: newSCStateUpdateBuffer(),
 		ccUpdateCh:       make(chan *balancer.ClientConnState, 1),
+		resolverErrCh:    make(chan error, 1),
 		done:             make(chan struct{}),
 		subConns:         make(map[*acBalancerWrapper]struct{}),
 	}
@@ -134,10 +137,22 @@
 			default:
 			}
 			if ub, ok := ccb.balancer.(balancer.V2Balancer); ok {
-				ub.UpdateClientConnState(*s)
+				if err := ub.UpdateClientConnState(*s); errors.Is(err, balancer.ErrBadResolverState) {
+					ccb.cc.resolveNow(resolver.ResolveNowOption{})
+				}
 			} else {
 				ccb.balancer.HandleResolvedAddrs(s.ResolverState.Addresses, nil)
 			}
+		case err := <-ccb.resolverErrCh:
+			select {
+			case <-ccb.done:
+				ccb.balancer.Close()
+				return
+			default:
+			}
+			if ub, ok := ccb.balancer.(balancer.V2Balancer); ok {
+				ub.ResolverError(err)
+			}
 		case <-ccb.done:
 		}

@@ -159,6 +174,26 @@
 	}
 }

+func (ccb *ccBalancerWrapper) resolverError(err error) {
+	select {
+	case <-ccb.done:
+		return
+	default:
+	}
+	select {
+	case ccb.resolverErrCh <- err:
+	default:
+		select {
+		case <-ccb.resolverErrCh:
+		default:
+		}
+		select {
+		case ccb.resolverErrCh <- err:
+		case <-ccb.done:
+		}
+	}
+}
+
 func (ccb *ccBalancerWrapper) close() {
 	close(ccb.done)
 }
